WebLink.url:
{! REQUIRESCRIPT("/soap/ajax/24.0/connection.js")}
var recordtype= sforce.connection.query("select name, id from recordtype where name='after finalize'");
var records = recordtype.getArray("records");
//alert(records);
try
{
if('{!apttus_proposal_proposal__c.Net_Total__c}' == '{!apttus_proposal_proposal__c.Payment_Net_Total__c}'){
 if('{!apttus_proposal_proposal__c.Approval_Status__c}' == 'No Need Of Approval'||'{!apttus_proposal_proposal__c.Approval_Status__c}' == 'Ready To Finalize')
{
sforce.connection.sessionid = '{!GETSESSIONID()}';
var quote = new sforce.SObject("apttus_proposal_proposal__c");
quote.id='{!apttus_proposal_proposal__c.Id}';
quote.Approval_Status__c='Finalized';
quote.RecordTypeId =records[0].Id;
var result = sforce.connection.update([quote]);
//alert(result);
}else{
	alert('Please Submit for Approval To Finalize');
}
}
else{
	alert('Net Total of Quote/Proposal and APAC Payment are not Equal');
}
}

catch (ex)
{
alert(ex);
}

location.reload(true);
